import { Suspense } from 'react'
import { Input } from "@/components/ui/input"
import { Button } from "@/components/ui/button"
import { Search } from "lucide-react"
import { DocumentsTable } from "./DocumentsTable"

// This is a Server Component that acts as the container
export default function VaultPage() {
    return (
        <div className="flex flex-1 flex-col gap-4 p-4 pt-0">
            <div className="flex items-center justify-between space-y-2">
                <h2 className="text-3xl font-bold tracking-tight">Vault</h2>
                <div className="flex items-center space-x-2">
                    <Button>Upload</Button>
                </div>
            </div>
            <div className="flex items-center space-x-2">
                <div className="relative flex-1">
                    <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
                    <Input placeholder="Search documents..." className="pl-8" />
                </div>
            </div>
            <div className="rounded-md border">
                {/* We pass a promise or let the component fetch its own data. 
            For best granularity, we use Suspense around the async data fetching part. */}
                <Suspense fallback={<TableSkeleton />}>
                    <DocumentsTable />
                </Suspense>
            </div>
        </div>
    )
}

function TableSkeleton() {
    return (
        <div className="w-full overflow-auto p-4 space-y-4">
            <div className="space-y-2">
                <div className="h-4 w-full bg-muted animate-pulse rounded"></div>
                <div className="h-4 w-3/4 bg-muted animate-pulse rounded"></div>
                <div className="h-4 w-full bg-muted animate-pulse rounded"></div>
            </div>
        </div>
    )
}
